{"src/runTasks.mjs":"/**
 * tasks是无参数异步函数数组，concurrency是并发上限；返回Promise。
 * 按输入顺序返回结果；任一任务失败时，等待已启动任务结束后以首个失败原因拒绝。
 * 并发上限会被规范为不小于1的整数；空数组直接返回空结果。
 */
export function runTasks(tasks, concurrency) {
  if (!Array.isArray(tasks)) {
    return Promise.reject(new TypeError('tasks must be an array'));
  }

  const total = tasks.length;
  if (total === 0) {
    return Promise.resolve([]);
  }

  let limit = Number(concurrency);
  if (!Number.isFinite(limit)) {
    limit = 1;
  }
  limit = Math.max(1, Math.floor(limit));
  if (limit > total) {
    limit = total;
  }

  return new Promise((resolve, reject) => {
    const results = new Array(total);
    let nextIndex = 0;
    let active = 0;
    let settled = false;
    let firstError;

    function launch() {
      if (settled) {
        return;
      }
      if (nextIndex >= total) {
        if (active === 0) {
          settled = true;
          resolve(results);
        }
        return;
      }

      const index = nextIndex++;
      const task = tasks[index];
      active++;

      let promise;
      try {
        if (typeof task !== 'function') {
          throw new TypeError('task at index ' + index + ' is not a function');
        }
        promise = Promise.resolve(task());
      } catch (error) {
        promise = Promise.reject(error);
      }

      promise.then(
        value => {
          results[index] = value;
          active--;
          launch();
        },
        error => {
          active--;
          if (!settled && firstError === undefined) {
            firstError = error;
          }
          if (active === 0) {
            if (!settled) {
              settled = true;
              reject(firstError);
            }
          } else {
            launch();
          }
        }
      );
    }

    for (let i = 0; i < limit; i++) {
      launch();
    }
  });
}
"}
